// Job: mirrors schedule.Job from the Python `schedule` package.
// Only the behavior exercised by the source script is reimplemented:
// unit selection (seconds/minutes/hours/days/weeks), .at() time
// validation for daily jobs, .do(), and the __repr__ string format.

import { ScheduleValueError } from './errors.mjs';

// Intervals are counted against the next week boundary in the real
// library; here we only need the period to exist for tag bookkeeping.
const TIME_UNITS = ['seconds', 'minutes', 'hours', 'days', 'weeks'];

export class Job {
  constructor(interval, scheduler = null) {
    this.interval = interval; // number of seconds/minutes/... between runs
    this.latest = null; // upper limit to the interval (unused here)
    this.jobFunc = null; // the callable to execute
    this.unit = null; // 'seconds' | 'minutes' | ... | 'weeks'
    this.atTime = null; // optional time of day the job runs at
    this.lastRun = null;
    this.nextRun = null;
    this.period = null;
    this.startDay = null;
    this.tags = new Set();
    this.scheduler = scheduler; // ref back to the Scheduler that owns us
  }

  get seconds() {
    return this._setUnit('seconds');
  }

  get minutes() {
    return this._setUnit('minutes');
  }

  get hours() {
    return this._setUnit('hours');
  }

  get days() {
    return this._setUnit('days');
  }

  get weeks() {
    return this._setUnit('weeks');
  }

  _setUnit(unit) {
    if (!TIME_UNITS.includes(unit)) {
      throw new ScheduleValueError('Invalid unit');
    }
    this.unit = unit;
    return this;
  }

  // Mirrors Job.at(): only the daily-job time format is needed here.
  // Python schedule validates with a regex equivalent to
  //   ^([0-2]\d):([0-5]\d)(:([0-5]\d))?$
  // and then range-checks the hour, raising ScheduleValueError with the
  // exact messages below (including the library's unformatted "{}").
  at(timeStr) {
    if (this.unit !== 'days') {
      throw new ScheduleValueError('Invalid unit');
    }
    const match = /^([0-2]\d):([0-5]\d)(:([0-5]\d))?$/.exec(timeStr);
    if (!match) {
      throw new ScheduleValueError(
        'Invalid time format for a daily job (valid format is HH:MM(:SS)?)'
      );
    }
    const hour = parseInt(match[1], 10);
    const minute = parseInt(match[2], 10);
    const second = match[4] !== undefined ? parseInt(match[4], 10) : 0;
    if (hour > 23) {
      throw new ScheduleValueError(
        'Invalid number of hours ({} is not between 0 and 23)'
      );
    }
    this.atTime = { hour, minute, second };
    return this;
  }

  do(jobFunc) {
    this.jobFunc = jobFunc;
    return this;
  }

  // Mirrors Job.__repr__ for the interval-1, lambda-doing jobs this
  // program creates: "Job(interval=1, unit=seconds, do=<lambda>, ...)".
  toString() {
    const name =
      this.jobFunc && this.jobFunc.displayName
        ? this.jobFunc.displayName
        : '<lambda>';
    return `Job(interval=${this.interval}, unit=${this.unit}, do=${name}, args=(), kwargs={})`;
  }
}

