// Scheduler: mirrors schedule.Scheduler plus the module-level default
// scheduler functions (every / cancel_job / get_jobs / clear).

import { CancelJobError } from './errors.mjs';
import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    this.jobs = []; // list of scheduled jobs
  }

  every(interval = 1) {
    const job = new Job(interval, this);
    this.jobs.push(job);
    return job;
  }

  // Mirrors Scheduler.cancel_job: removes the job, raising
  // CancelJobError if it is not scheduled.
  cancelJob(job) {
    const index = this.jobs.indexOf(job);
    if (index === -1) {
      throw new CancelJobError('Cannot cancel a job that is not scheduled');
    }
    this.jobs.splice(index, 1);
  }

  getJobs(tag = null) {
    if (tag === null || tag === undefined) {
      return this.jobs.slice();
    }
    return this.jobs.filter((job) => job.tags.has(tag));
  }

  // Mirrors Scheduler.clear(): with no tag, removes every job.
  clear(tag = null) {
    if (tag === null || tag === undefined) {
      this.jobs = [];
    } else {
      this.jobs = this.jobs.filter((job) => !job.tags.has(tag));
    }
  }
}

// Module-level default scheduler, mirroring schedule/__init__.py.
const defaultScheduler = new Scheduler();

export function every(interval = 1) {
  return defaultScheduler.every(interval);
}

export function cancel_job(job) {
  return defaultScheduler.cancelJob(job);
}

export function get_jobs(tag = null) {
  return defaultScheduler.getJobs(tag);
}

export function clear(tag = null) {
  return defaultScheduler.clear(tag);
}

