// Minimal argument parser mimicking Python's argparse for this script:
// required string options --a, --b, --c, --d, supporting both
// "--x val" and "--x=val" forms, plus -h/--help.

import { basename } from 'node:path';

const PROG = basename(process.argv[1] || 'test10.mjs');
const OPTIONS = ['a', 'b', 'c', 'd'];

function usageLine() {
  return `usage: ${PROG} [-h] --a A --b B --c C --d D`;
}

function printHelp() {
  const lines = [
    usageLine(),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
    '  --d D',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function errorExit(message) {
  process.stderr.write(usageLine() + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv = process.argv.slice(2)) {
  const result = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      printHelp();
      process.exit(0);
    }

    let name = null;
    let value = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        value = token.slice(eq + 1);
      } else {
        name = token.slice(2);
      }
    }

    if (name !== null && OPTIONS.includes(name)) {
      if (value === null) {
        if (i + 1 >= argv.length) {
          errorExit(`argument --${name}: expected one argument`);
        }
        value = argv[++i];
      }
      result[name] = value; // argparse: last occurrence wins
    } else {
      extras.push(token);
    }
  }

  const missing = OPTIONS.filter((opt) => !(opt in result));
  if (missing.length > 0) {
    errorExit(
      `the following arguments are required: ${missing
        .map((opt) => `--${opt}`)
        .join(', ')}`
    );
  }

  if (extras.length > 0) {
    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return result;
}

