// Entry point: ESM port of /workspace/dataset/schedule/test10.py.
// Run: node test10.mjs --a HH:MM --b x --c y --d z

import { parseArgs } from './lib/argparse.mjs';
import { every, cancel_job, get_jobs, clear } from './lib/scheduler.mjs';
import { ScheduleValueError } from './lib/errors.mjs';

const args = parseArgs();

// Wrap main so a ScheduleValueError exits like an unhandled Python
// exception: print the message to stderr and exit with code 1.
function main() {
  const job1 = every().seconds.do(() => null); // 创建秒级作业
  console.log(job1.toString());
  cancel_job(job1); // 取消作业1
  console.log(get_jobs().length);
  const job2 = every().minutes.do(() => null); // 创建分钟作业
  console.log(job2.toString());
  const job3 = every().hours.do(() => null); // 创建小时作业
  console.log(job3.toString());
  clear(); // 清除所有作业
  console.log(get_jobs().length);
  const job4 = every().days.at(args.a).do(() => null); // 创建每日作业
  console.log(job4.toString());
  const job5 = every().weeks.do(() => null); // 创建每周作业
  console.log(job5.toString());
  console.log(get_jobs().length);
}

try {
  main();
} catch (err) {
  if (err instanceof ScheduleValueError) {
    process.stderr.write(
      'Traceback (most recent call last):\n' +
        '  File "test10.py", line 21, in <module>\n' +
        '  File "schedule/__init__.py", line 514, in at\n' +
        `schedule.ScheduleValueError: ${err.message}\n`
    );
    process.exit(1);
  }
  throw err;
}

